abstract class Employee {
    private String name;
    private String employeeId;
    public Employee(String name, String employeeId) {
        this.name = name;
        this.employeeId = employeeId;
    }
    public abstract double calculateSalary();
    public abstract String getDesignation();
    public void printPaySlip() {
        System.out.println("=== Pay Slip ===");
        System.out.println("ID         : " + employeeId);
        System.out.println("Name       : " + name);
        System.out.println("Designation: " + getDesignation());
        System.out.printf("Net Salary : ₹%.2f%n", calculateSalary());
    }
    public String getName() { return name; }
    public String getEmployeeId() { return employeeId; }
}
class FullTimeEmployee extends Employee {
    private double baseSalary;
    public FullTimeEmployee(String n, String id, double base) { super(n, id); this.baseSalary = base; }
    public double calculateSalary() { return baseSalary + baseSalary * 0.20; } // base + 20% HRA
    public String getDesignation() { return "Full-Time Engineer"; }
}

