6. Refactor this code using the Template Method Pattern with an abstract class:
void exportToCSV(List<Order> orders) {
    printHeader();
    for (Order o : orders) System.out.println(o.getId() + "," + o.getTotal());
    printFooter();
}
void exportToHTML(List<Order> orders) {
    System.out.println("<table>");
    for (Order o : orders) System.out.println("<tr><td>" + o.getId() + "</td></tr>");
    System.out.println("</table>");
}

