abstract class OrderExporter {
    public final void export(List<Order> orders) { // template method
        printHeader();
        for (Order o : orders) printRow(o);
        printFooter();
    }
    protected abstract void printHeader();
    protected abstract void printRow(Order o);
    protected abstract void printFooter();
}
class CsvOrderExporter extends OrderExporter {
    protected void printHeader() { System.out.println("id,total"); }
    protected void printRow(Order o) { System.out.println(o.getId() + "," + o.getTotal()); }
    protected void printFooter() { System.out.println("# end"); }
}
class HtmlOrderExporter extends OrderExporter {
    protected void printHeader() { System.out.println("<table>"); }
    protected void printRow(Order o) { System.out.println("<tr><td>" + o.getId() + "</td></tr>"); }
    protected void printFooter() { System.out.println("</table>"); }
}

Yes — an abstract class can implement an interface without providing implementations for any or all of the interface's abstract methods. The abstract class simply inherits those obligations and passes them down to its concrete subclasses.
interface Drawable { void draw(); void resize(int factor); }
abstract class AbstractShape implements Drawable {
    // Does NOT implement draw() or resize() — they become abstract methods inherited by subclasses
    protected String color;
    public AbstractShape(String color) { this.color = color; }
    public String getColor() { return color; }
    // Could implement one and leave the other: 
    public void resize(int factor) { System.out.println("Resizing by " + factor); }
    // draw() is still abstract — subclass must implement
}
class Circle extends AbstractShape {
    private double radius;
    public Circle(String color, double radius) { super(color); this.radius = radius; }
    public void draw() { System.out.println("Drawing Circle r=" + radius + " color=" + color); }
    // resize() inherited from AbstractShape — no need to re-implement
}

